            red_ok = fresh and stale_refused
            red_ok = red_ok and TM.forged_neighbour_plant() == (True, True, True)
            red_ok = red_ok and TM.lifted_certificate_plant()
            occ = frozenset({(33, 33, 33), (33, 33, 34)})
