_BRIEF_FALSIFIER = re.compile(r"<!--\s*brief-falsifier:\s*([A-Za-z0-9_:.\-]+)\s*-->")


def _rows_by_stage():
    """row-name -> stage method, derived from verify.py's OWN SOURCE rather than from a naming
    convention. `autoroute-enforce` belongs to `autoroute` because the literal appears inside that
    method, not because the strings share a prefix — this repo has retired four heuristics for
    reading structure out of names."""
    src = io.open(os.path.abspath(__file__), encoding="utf-8").read()
    out, cur = {}, None
    for line in src.splitlines():
        m = re.match(r"    def (\w+)\(self\)", line)
        if m:
            cur = m.group(1)
        for r in re.findall(r'self\.record\(\s*"([^"]+)"', line):
            if cur:
                out.setdefault(r, cur)
    return out


def _stage_sources():
    """stage method name -> its full source text, sliced out of verify.py's OWN source. Shared by the
    brief-falsifier checker and the unrelated-row derivation so both read structure the same way."""
    src = io.open(os.path.abspath(__file__), encoding="utf-8").read()
    out, cur, buf = {}, None, []
    for line in src.splitlines(True):
        m = re.match(r"    def (\w+)\(self\)", line)
        if m:
            if cur:
                out[cur] = "".join(buf)
            cur, buf = m.group(1), []
        buf.append(line)
    if cur:
        out[cur] = "".join(buf)
    return out


def _read_brief_markers(mod):
    """The brief-falsifier markers actually present in docs/{mod}_brief.md, or None if the brief is
    missing. Factored out as the DEFAULT marker source so the self-test can inject synthetic markers
    and plant each failure direction deterministically, without touching disk."""
    rel = os.path.join("docs", f"{mod}_brief.md")
    try:
        text = io.open(os.path.join(ROOT, rel), encoding="utf-8").read()
    except OSError:
        return None
    return _BRIEF_FALSIFIER.findall(text)


def brief_falsifier_problems(row_names, marker_of=_read_brief_markers):
    """The three conditions a brief's falsifier marker must satisfy. Returns a list of problems.

    (1) the marker is present EXACTLY ONCE — zero means the brief makes no checkable claim, two means
        it is ambiguous about which row refutes it;
    (2) the named row EXISTS in this run's live row set — exogenous to the doc;
    (3) the brief's MODULE is genuinely among that row's measured inputs, established by finding the
        module imported inside the stage method that records the row. Without (3) a brief could cite
        any always-green row and be syntactically valid while explaining nothing — the citation would
        be a decoration with a checkmark.

    `marker_of` supplies each module's markers (default: read the brief file); the self-test injects
    it to plant nonexistent-row and unrelated-row defects deterministically and file-free."""
    by_stage = _rows_by_stage()
    stage_src = _stage_sources()
    out = []
    for mod in BRIEFS_REQUIRING_A_FALSIFIER:
        rel = os.path.join("docs", f"{mod}_brief.md")
        hits = marker_of(mod)
        if hits is None:
            out.append((rel, "missing", mod, "no brief"))
            continue
        if len(hits) != 1:
            out.append((rel, "marker-count", str(len(hits)), "1"))
            continue
        row = hits[0]
        if row not in row_names:
            out.append((rel, "unknown-row", row, "live row set"))
            continue
        st = by_stage.get(row)
        body = stage_src.get(st, "")
        if not re.search(r"import\s+%s(\s|$|\s+as\s)" % re.escape(mod), body):
            out.append((rel, "row-does-not-measure", row, f"{st} never imports {mod}"))
    return out


class BriefEvidenceError(Exception):
    """The brief-falsifiers evidence could not be DERIVED cleanly — a brief was dropped from the
    derivation, or a hand-supplied count disagreed with it. Raised so a stale number or a missing
    brief reddens instead of quietly narrowing the enumeration."""


def _an_unrelated_live_row(row_names, mod):
    """A live gate row whose recording stage does NOT import `mod`, DERIVED (never named) from
    verify.py's own source so it cannot rot when stages move. Used to plant direction (2): a brief
    citing this real, live row is syntactically valid yet explains nothing about `mod`."""
    by_stage = _rows_by_stage()
    stage_src = _stage_sources()
    for row in sorted(row_names):
        st = by_stage.get(row)
        if st is None:
            continue
        if not re.search(r"import\s+%s(\s|$|\s+as\s)" % re.escape(mod), stage_src.get(st, "")):
            return row
    return None


def brief_evidence_facts(row_names, marker_of=_read_brief_markers):
    """The DERIVED semantic content of the brief-falsifiers evidence: the canonical, SORTED tuple of
    (module, row) pairs — each enforced brief that passes all three conditions paired with the gate
    row its marker names. Sorting makes it order-invariant (reordering BRIEFS_REQUIRING_A_FALSIFIER
    changes nothing); it is built from the live markers/rows/bindings, never described in prose. A
    brief with ANY problem is absent, so the derived cover disagrees with the required set."""
    bad = {p[0] for p in brief_falsifier_problems(row_names, marker_of)}
    facts = []
    for mod in BRIEFS_REQUIRING_A_FALSIFIER:
        rel = os.path.join("docs", f"{mod}_brief.md")
        if rel in bad:
            continue
        facts.append((mod, marker_of(mod)[0]))
    return tuple(sorted(facts))


def brief_evidence(row_names, marker_of=_read_brief_markers, claimed_count=None):
    """DERIVE the brief-falsifiers evidence string from (markers, live rows, module bindings). The
    count is len(facts) and the enumeration is the canonical facts — BOTH read off the derivation,
    never hand-maintained. Raises BriefEvidenceError if the derivation does not cover every enforced
    brief (a dropped or invalid brief) or if a supplied `claimed_count` disagrees with it."""
    facts = brief_evidence_facts(row_names, marker_of)
    covered = {m for m, _ in facts}
    required = set(BRIEFS_REQUIRING_A_FALSIFIER)
    if covered != required:
        raise BriefEvidenceError(f"derivation omits {sorted(required - covered)}")
    n = len(facts)
    if claimed_count is not None and claimed_count != n:
        raise BriefEvidenceError(f"count {claimed_count} disagrees with the derived {n}")
    listing = ", ".join(f"{m}->{r}" for m, r in facts)
    return (f"each of the {n} enforced briefs names the gate row that would refute it — an "
            f"enumeration DERIVED from the live markers, rows and module bindings, not described in "
            f"prose ({listing}) — and the citation is CHECKED three ways: the marker appears exactly "
            f"once, the row exists in this run's live row set, and the brief's module is genuinely "
            f"imported by the stage that records that row, the third condition stopping a "
            f"syntactically valid citation to an unrelated always-green row. The row->stage map is "
            f"derived from verify.py's own source rather than from a name prefix")


def brief_evidence_plants_bite(row_names):
    """RED-FIRST: the derived evidence must BITE in each independent failure direction, or a clean
    derivation means nothing (L23, paid three times). Each direction is planted SEPARATELY against
    synthetic markers, file-free:

      (1) a brief names a NONEXISTENT row        -> unknown-row AND derivation incomplete;
      (2) a brief names a real but UNRELATED row -> row-does-not-measure;
      (3) a valid brief is OMITTED               -> derivation != required set;
      (4) a hand-edited COUNT disagrees          -> BriefEvidenceError;
      (5) REORDER + WHITESPACE-REWRAP is a no-op -> identical canonical facts (semantic, not text).

    Returns True iff every RED direction reddens and the invariance control holds."""
    real = {mod: _read_brief_markers(mod) for mod in BRIEFS_REQUIRING_A_FALSIFIER}
    victim = BRIEFS_REQUIRING_A_FALSIFIER[0]

    def swap(markers):
        return lambda mod: markers if mod == victim else real.get(mod)

    # (1) nonexistent row: both the checker (unknown-row) and the derivation (incomplete) must object.
    m1 = swap(["no-such-row-000"])
    d1_checker = any(p[1] == "unknown-row" for p in brief_falsifier_problems(row_names, m1))
    try:
        brief_evidence(row_names, m1); d1_derive = False
    except BriefEvidenceError:
        d1_derive = True
    one = d1_checker and d1_derive

    # (2) real but unrelated row, DERIVED not named, so the plant cannot rot when stages move.
    unrelated = _an_unrelated_live_row(row_names, victim)
    two = (unrelated is not None and
           any(p[1] == "row-does-not-measure"
               for p in brief_falsifier_problems(row_names, swap([unrelated]))))

    # (3) a valid brief omitted from the derivation.
    try:
        brief_evidence(row_names, swap([])); three = False
    except BriefEvidenceError:
        three = True

    # (4) a hand-edited count disagreeing with the derivation — the exact staleness this row carried.
    try:
        brief_evidence(row_names, _read_brief_markers,
                       claimed_count=len(BRIEFS_REQUIRING_A_FALSIFIER) + 1)
        four = False
    except BriefEvidenceError:
        four = True

    # (5) reorder + whitespace-rewrap is a SEMANTIC no-op (the wrapped-phrase defect class, paid
    #     repeatedly): the output is sorted (order-invariant), and re-parsing every marker with
    #     padded whitespace yields the identical canonical facts.
    canonical = brief_evidence_facts(row_names)
    rewrapped = {mod: _BRIEF_FALSIFIER.findall(
                     "<!--   brief-falsifier:   %s   -->" % (real[mod][0] if real[mod] else "x"))
                 for mod in BRIEFS_REQUIRING_A_FALSIFIER}
    five = (list(canonical) == sorted(canonical) and
            brief_evidence_facts(row_names, lambda mod: rewrapped.get(mod)) == canonical)

    return one and two and three and four and five


def _numeric_signature(detail: str) -> str:
    """Every NUMBER in an evidence string, in order. Evidence strings deliberately carry MEASURED
    values (L16), so a change here is a change in what was measured — which is the signal. Prose
    edits move `len(detail)` and leave this alone, and the drift report separates the two, because
    "I rewrote a sentence" and "the census moved" are different events."""
    import re as _re
    return ",".join(_re.findall(r"-?\d+(?:\.\d+)?", detail))


def _classify_drift(now, base):
    """THE COMPARATOR, deliberately separated from the git/subprocess I/O around it so it can be
    FALSIFIED. Both arguments map row-name -> (status, numeric-signature, evidence-length); a
    signature of None means the baseline could not supply one (the [DEGRADED] path), and then only
    status is comparable. Returns the report lines; an EMPTY list is what earns the words "no drift".

    Why this is a separate function at all: the baseline's rows come from a worktree at HEAD, but
    the comparison runs in the WORKING TREE. The ruler is therefore inside what it measures, and a
    fail-open edit here — `if False and num_n != num_b:` — makes the report print "no drift" with
    full confidence while a measured value really moved. That is DEMONSTRATED, not feared: planted
    against `cohort-gap`'s (4,1,1) -> (4,1,9), the report stayed silent. A ruler cannot score
    itself, so the gate scores it instead (`tests/test_drift_report.py`)."""
    lines = []
    for n in now:
        if n not in base:
            lines.append(f"  [NEW]  {n}\n")
    for n in base:
        if n not in now:
            lines.append(f"  [GONE] {n}\n")
    for n in now:
        if n not in base:
            continue
        ok_n, num_n, len_n = now[n]
        ok_b, num_b, len_b = base[n]
        if ok_n != ok_b:
            lines.append(f"  [RED]  {n}: {ok_b} -> {ok_n}\n")
        if num_b is None:                       # degraded baseline: status was all it could give
            continue
        if num_n != num_b:
            lines.append(f"  [NUM]  {n}: measured values moved\n"
                         f"           - {num_b[:90]}\n           + {num_n[:90]}\n")
        elif len_n != len_b:
            lines.append(f"  [TEXT] {n}: prose only ({len_b} -> {len_n} chars), numbers unmoved\n")
    return lines


def _drift_report(only: str, rows) -> str:
    """Compare this subset run against the SAME stages run from a git worktree at HEAD. The baseline
    is DERIVED FROM THE COMMIT, never read from a transcript lying around: a stale `gate1.txt` has no
    provenance binding it to any code, so a diff against it cannot distinguish 'my edit is wrong' from
    'the baseline is old' — the same defect class doc-currency exists to prevent."""
    import subprocess as _sp
    import tempfile as _tf
    import shutil as _sh
    wt = _tf.mkdtemp(prefix="urdr-baseline-")
    out = ["-" * 70 + "\n", "DRIFT vs HEAD (baseline built from the commit, not from a transcript)\n"]
    try:
        r = _sp.run(["git", "-C", ROOT, "worktree", "add", "-q", "--detach", wt, "HEAD"],
                    capture_output=True, text=True)
        if r.returncode:
            return "".join(out) + f"  [SKIP] no baseline: {r.stderr.strip()[:80]}\n"
        env = dict(os.environ, PYTHONHASHSEED="0", PYTHONUTF8="1")
        b = _sp.run([sys.executable, os.path.join(wt, "verify.py"), "--only", only, "--emit-rows"],
                    capture_output=True, text=True, env=env, cwd=wt)
        base = {}
        for line in b.stdout.splitlines():
            parts = line.split("\t")
            if len(parts) == 4:
                base[parts[0]] = (parts[1], parts[2], parts[3])
        now = {n: (str(int(ok)), _numeric_signature(d), str(len(d))) for n, ok, d in rows}
        degraded = False
        if not base:
            # BOOTSTRAP: a baseline commit that predates `--emit-rows` cannot report evidence
            # signatures. Fall back to its plain `--only` output, which gives STATUS drift only, and
            # SAY SO rather than printing "no drift" — a comparison that silently lost half its
            # resolution is worse than one that admits it.
            b2 = _sp.run([sys.executable, os.path.join(wt, "verify.py"), "--only", only],
                         capture_output=True, text=True, env=env, cwd=wt)
            for line in b2.stdout.splitlines():
                if line.startswith("[PASS] ") or line.startswith("[FAIL] "):
                    base[line[7:].strip()] = ("1" if line.startswith("[PASS]") else "0", None, None)
            degraded = bool(base)
            if not base:
                return "".join(out) + "  [SKIP] baseline produced no rows (new stage?)\n"
            out.append("  [DEGRADED] baseline predates --emit-rows: STATUS drift only, no evidence\n"
                       "             signatures. Upgrades automatically once this lands.\n")
        out.append(f"  rows {len(now)} here / {len(base)} at HEAD\n")
        drift = _classify_drift(now, base)
        out.extend(drift)
        if not drift:
            out.append("  no drift" + (" in status (evidence not comparable)" if degraded else "")
                       + "\n")
    finally:
        _sp.run(["git", "-C", ROOT, "worktree", "remove", "--force", wt],
                capture_output=True, text=True)
        _sh.rmtree(wt, ignore_errors=True)
    out.append(
        "  WHAT THIS CANNOT SEE — and the second item is this tool itself:\n"
        "  (1) doc-currency and doc-staleness, STRUCTURALLY and not just in practice: doc_currency\n"
        "      runs LAST and reads len(self.rows), so EVERY row in the gate is one of its inputs and\n"
        "      no subset can supply them (they are WITHHELD, see [WITHHELD] above). Likewise the\n"
        "      vacuity floor, the tamper selftest, and any cross-stage effect.\n"
        "  (2) THE COMPARATOR. The baseline's rows come from HEAD, but the comparison is executed by\n"
        "      the WORKING TREE's _classify_drift. Edit it to fail open and this report says 'no\n"
        "      drift' with full confidence — demonstrated, not feared. That is why _classify_drift\n"
        "      is pure and carries unit falsifiers (tests/test_drift_report.py): the ruler cannot\n"
        "      score itself, so the gate scores it.\n"
        "  A fast partial check, explicitly not a substitute for the gate.\n")
    return "".join(out)


def main() -> int:
    global SUBSET_ONLY
    _utf8_stdio()
    os.environ["PYTHONHASHSEED"] = "0"
    only = None
    profile = "--profile" in sys.argv
    if "--only" in sys.argv:
        only = sys.argv[sys.argv.index("--only") + 1]
    SUBSET_ONLY = only            # set BEFORE Gate() so no stage can race the flag
    gate = Gate()
    for _name in STAGE_ORDER:
        if only is not None and only not in _name:
            continue
        _fn = getattr(gate, _name)
        if profile:
            _t = _time.perf_counter()
            _fn()
            sys.stderr.write(f"{_time.perf_counter() - _t:8.2f}s  {_name}\n")
            sys.stderr.flush()
        else:
            _fn()
    if only is not None:
        # DEV LOOP ONLY. A subset run is NOT a gate pass: the vacuity floor, the tamper selftest and
        # every cross-cutting row are absent by construction, so it prints rows and refuses to grade.
        rows = [(n, ok, d) for n, ok, d in gate.rows]
        if "--emit-rows" in sys.argv:                       # machine form, for --diff's baseline
            for n, ok, d in rows:
                sys.stdout.write(f"{n}\t{int(ok)}\t{_numeric_signature(d)}\t{len(d)}\n")
            return 1 if gate.failed else 0
        for n, ok, _d in rows:
            sys.stdout.write(f"[{'PASS' if ok else 'FAIL'}] {n}\n")
        for _n, _why in gate.withheld:
            sys.stdout.write(f"[WITHHELD] {_n}\n           {_why}\n")
        if "--diff" in sys.argv:
            sys.stdout.write(_drift_report(only, rows))
        sys.stdout.write(f"SUBSET RUN — {len(rows)} rows, NOT A GATE PASS\n")
        return 1 if gate.failed else 0

    return gate.report()


if __name__ == "__main__":
    sys.exit(main())
